// CSD_RATIONALE_BEGIN
// SMILES-focused constrained decoding with visible constrained spans. The
// strategy tracks the ordinary visible output (`generated`), whether decoding
// is currently inside a constrained SMILES span, and the active constrained
// prefix (`currentConstrainedOut`). Outside a span it generates freely in short
// chunks so that a naturally emitted "<<" delimiter can be observed without
// paying per-token dispatch overhead.
// 
// Inside a span, the parser remains the hard authority. The strategy measures
// local parser narrowness with `ValidTokenCount` and `DeadEndDetection`, uses a
// one-token hard constrained step in narrow states, and otherwise uses a
// bounded symbol step (`ConstrainedSymbolInGenerated`) so a short valid SMILES
// fragment can be accepted at once. When a constrained prefix becomes complete,
// the strategy closes the visible span. If the parser reports a dead-end-like
// narrow state after some growth, the strategy repairs by rolling back the
// constrained suffix to a valid prefix and continues.
// 
// This tracked state supports valid SMILES generation because every committed
// inside-span extension is parser-valid, rollback preserves parser validity,
// and visible delimiter/state transitions keep the constrained substring aligned
// with the parser-controlled SMILES segment.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span chunk branch, `insideConstrainedOut`
//   stays false unless `UnconstrainedChunk` stops on "<<"; in that case
//   `EnterObservedConstrainedSpan` sets `currentConstrainedOut := []`, which is
//   valid by the method precondition `parser.IsValidPrefix([])`. In the
//   complete-prefix branch, `CloseConstrainedSpan` exits constrained mode, so
//   the implication becomes vacuous.
// parser_validity: In the rollback branch, `RollbackConstrainedSuffix` repairs
//   the active constrained suffix to a parser-valid prefix, so keeping
//   `insideConstrainedOut := true` preserves the invariant. In the narrow
//   one-token branch, `ConstrainedStep` returns EOS or a parser-valid next
//   token; on the non-EOS path `AppendConstrainedToken` preserves validity. In
//   the symbol branch, `ConstrainedSymbolInGenerated` returns `currentOut` that
//   is parser-valid, so assigning it preserves the invariant.
// progress: In the outside-span chunk branch, `steps := steps + stepsUsed` and
//   `UnconstrainedChunk` appends at most `stepsUsed` visible tokens, so
//   `|generated| <= |generatedPrefix| + steps` is preserved. If the chunk ends
//   on EOS, EOS may consume budget without visible growth, which still respects
//   the bound.
// progress: In the close branch, `CloseConstrainedSpan` consumes 1 step and
//   appends at most one visible delimiter, so the bound is preserved. In the
//   rollback branch, rollback shrinks or preserves visible output while we
//   still increment `steps` by 1, so the inequality remains true.
// progress: In the narrow constrained-token branch, `ConstrainedStep` consumes
//   1 step and `AppendConstrainedToken` appends at most one token, while EOS
//   consumes a step without visible growth. In the symbol branch,
//   `ConstrainedSymbolInGenerated` consumes `stepsUsed` token-steps and visible
//   growth is at most the accepted valid prefix length, which is no more than
//   `stepsUsed`, even if some consumed tokens were rejected suffix tokens or
//   EOS. Therefore the length bound is preserved in every branch.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var rollbackLimit: nat := 32;
var narrowThreshold: nat := 8;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var chunkBudget: nat := maxSteps - steps;
    var chunkedGenerated, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedGenerated;
    steps := steps + stepsUsed;
    if stoppedOnEos {
      break;
    } else if stoppedOnOpenSpan {
      var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := enteredGenerated;
      insideConstrainedOut := enteredInside;
      currentConstrainedOut := enteredCurrent;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= rollbackLimit &&
            helpers.DeadEndDetection(parser, currentConstrainedOut, 1) {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    if validCount <= narrowThreshold {
      var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    } else {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget == 0 || stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolCurrent, hitEos, symbolSteps := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      insideConstrainedOut := true;
      currentConstrainedOut := symbolCurrent;
      steps := steps + symbolSteps;
      if hitEos {
        break;
      }
    }
  }
}

cost := steps;

